import { toAssetTypeParam } from "../asset-type.types.js";
import { BaseReader } from "../base-reader.js";
import { UserOrdersSchema, UserOrdersWsMessageSchema, } from "./user-order-history.types.js";
export class UserOrderHistoryReader extends BaseReader {
    async getByAddr({ subAddr, limit, offset, startTimestamp, endTimestamp, sortDir, assetType = "perp", fetchOptions, }) {
        const queryParams = {
            account: subAddr,
        };
        if (limit !== undefined)
            queryParams.limit = limit.toString();
        if (offset !== undefined)
            queryParams.offset = offset.toString();
        if (startTimestamp !== undefined)
            queryParams.start_timestamp = startTimestamp.toString();
        if (endTimestamp !== undefined)
            queryParams.end_timestamp = endTimestamp.toString();
        if (sortDir !== undefined)
            queryParams.sort_dir = sortDir;
        const assetTypeParam = toAssetTypeParam(assetType);
        if (assetTypeParam !== undefined)
            queryParams.asset_type = assetTypeParam;
        const response = await this.getRequest({
            schema: UserOrdersSchema,
            url: `${this.deps.config.tradingHttpUrl}/api/v1/order_history`,
            queryParams,
            options: fetchOptions,
        });
        return response.data;
    }
    /**
     * Subscribe to user order updates
     * @param subAddr The subaccount address of the user to subscribe to
     * @param onData Callback function for received user order data
     * @returns A function to unsubscribe from the user order updates
     */
    subscribeByAddr(subAddr, onData) {
        const topic = `order_updates:${subAddr}`;
        return this.deps.ws.subscribe(topic, UserOrdersWsMessageSchema, onData);
    }
}
